# Lunar Konstruksi - Home polish: preserve first 2 sections, redesign section 3 onward
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-Phase([string]$Message) { Write-Host "[HOME POLISH] $Message" -ForegroundColor Cyan }
function Fail-Phase([string]$Message) { Write-Host ""; Write-Host "[HOME POLISH] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Decode([string]$Value) { return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Value)) }
function Write-Utf8NoBom([string]$Path, [string]$Content) {
  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $encoding)
}

$repoRoot = (& git rev-parse --show-toplevel 2>$null)
if (-not $repoRoot) { Fail-Phase "Jalankan dari root repository Lunar Konstruksi." }
$repoRoot = $repoRoot.Trim()
Set-Location $repoRoot
$trackedStatus = & git status --porcelain --untracked-files=no
if ($trackedStatus) { Write-Host $trackedStatus; Fail-Phase "Ada perubahan tracked. Commit/stash dulu agar backup aman." }

$required = @(
  "components/site/formwork/home.tsx",
  "components/site/formwork/decor.tsx",
  "components/site/formwork/data.ts",
  "components/site/formwork/media.tsx",
  "components/site/formwork/header.tsx",
  "components/site/formwork/footer.tsx"
)
$missing = @($required | Where-Object { -not (Test-Path -LiteralPath $_) })
if ($missing.Count -gt 0) { $missing | ForEach-Object { Write-Host "  - $_" }; Fail-Phase "Struktur Formwork belum lengkap." }

$backupDir = Join-Path $repoRoot (".lunar-backups/home-polish-" + (Get-Date -Format "yyyyMMdd-HHmmss"))
New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
Copy-Item "components/site/formwork/home.tsx" (Join-Path $backupDir "home.tsx") -Force
Copy-Item "components/site/formwork/decor.tsx" (Join-Path $backupDir "decor.tsx") -Force
Write-Phase "Backup: $backupDir"

$payload_home_tsx = ""
Write-Utf8NoBom (Join-Path $repoRoot "components/site/formwork/home.tsx") (Decode $payload_home_tsx)
Write-Phase "write components/site/formwork/home.tsx"

$payload_decor_tsx = ""
Write-Utf8NoBom (Join-Path $repoRoot "components/site/formwork/decor.tsx") (Decode $payload_decor_tsx)
Write-Phase "write components/site/formwork/decor.tsx"

Write-Host ""
Write-Host "[HOME POLISH] Selesai." -ForegroundColor Green
Write-Host "Dua section awal dipertahankan + detail konstruksi/font dipoles." -ForegroundColor Green
Write-Host "Section 3 sampai akhir dirombak: project dossier, site sequence, precision panel, field crew, field memo, CTA." -ForegroundColor Green
Write-Host ""
Write-Host "Validasi:" -ForegroundColor Cyan
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
Write-Host "  npm run dev"
